"""Symmetric first-contact caps for piecewise linear moving profile fronts.

This fills gaps between the sampled normal rays. It is not a certificate for
the final curved interpolant; its clearance and mesh checks remain required.
Incoming profile endpoints stay fixed during the contact calculation.
"""
import bpy
from . import curved_sector_coordinates as charts
c=charts.c


def contact():
    name='Prochitecture Streets / Moving profile point segment contact v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    for key in ('Point','Velocity','Start','End','Start Velocity','End Velocity'):g.socket(key,'NodeSocketVector')
    g.socket('Factor','NodeSocketFloat','OUTPUT');inp=g.node('NodeGroupInput')
    read=lambda key:c._vec(g,inp.outputs[key])
    D=c._sub(read('Point'),read('Start'));E=c._sub(read('Velocity'),read('Start Velocity'))
    S=c._sub(read('End'),read('Start'));F=c._sub(read('End Velocity'),read('Start Velocity'))
    a=c._cross(E,F);b=c._cross(D,F)+c._cross(E,S);cc=c._cross(D,S)
    quadratic=g.math('GREATER_THAN',g.math('ABSOLUTE',a),1e-12)
    discriminant=b*b-4.*a*cc;real=1.-g.math('LESS_THAN',discriminant,0.)
    q=-.5*(b+c.choose(g,g.math('LESS_THAN',b,0.),-1.,1.)*g.math('SQRT',g.math('MAXIMUM',discriminant,0.)))
    nonzero_q=g.math('GREATER_THAN',g.math('ABSOLUTE',q),1e-12)
    nonzero_b=g.math('GREATER_THAN',g.math('ABSOLUTE',b),1e-12)
    roots=((q/c.choose(g,quadratic,a,1.),quadratic*real),
           (cc/c.choose(g,nonzero_q,q,1.),quadratic*real*nonzero_q),
           (-cc/c.choose(g,nonzero_b,b,1.),(1.-quadratic)*nonzero_b))
    factor=1e8
    for t,valid in roots:
        edge=c._add(S,c._scale(F,t));delta=c._add(D,c._scale(E,t));length=c._dot(edge,edge)
        u=c._dot(delta,edge)/g.math('MAXIMUM',length,1e-20)
        valid=valid*g.math('GREATER_THAN',t,1e-7)*g.math('GREATER_THAN',length,1e-12)
        valid=valid*g.math('GREATER_THAN',u,-1e-7)*g.math('LESS_THAN',u,1.0000001)
        factor=g.math('MINIMUM',factor,c.choose(g,valid,t,1e8))
    out=g.node('NodeGroupOutput');g.bind(factor,out.inputs['Factor']);return g.g


def cap(g,src,at,count,*,exact_mouths=False,peer=None,reduce=True):
    """Cap each moving sample in both roles: point and segment endpoint.

    The same contact factor must constrain all three participating samples.
    Updating only the querying point misses contacts with the other segment.
    Exact mouth mode excludes only a prescribed common fixed endpoint. Two
    separately rounded copies of that endpoint otherwise make a degenerate
    contact polynomial appear to have an arbitrary positive-time root.
    """
    index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]) if peer is None else peer
    field=lambda name,kind='FLOAT':c.named(g,'st_cg_'+name,kind)
    mouths=c._stat(g,src,field('owner','INT'),'Max')+1.
    def motion(row=None):
        read=lambda name,kind='FLOAT':field(name,kind) if row is None else c._read(g,src,'st_cg_'+name,row,kind)
        p=c._vec(g,g.position() if row is None else c._sample(g,src,g.position(),row,'FLOAT_VECTOR'))
        t=read('t');fixed=g.math('LESS_THAN',t,1e-7)+g.math('GREATER_THAN',t,1.-1e-7)
        v=c._scale(c._vec(g,read('normal','FLOAT_VECTOR')),read('nominal'))
        owner=read('owner','INT');mouth=c.choose(g,g.math('GREATER_THAN',t,1.-1e-7),g.math('MODULO',owner+1.,mouths),owner)
        return c._add(p,c._scale(v,fixed)),c._scale(v,1.-fixed),owner,fixed,mouth
    P,V,owner,fixed,own_mouth=motion(at)
    A,VA,other,fixed_a,mouth_a=motion(peer);B,VB,next_owner,fixed_b,mouth_b=motion(g.math('MINIMUM',index+1.,count-1.))
    different=1.-g.math('COMPARE',owner,other)
    def test(p,v,a,b,va,vb,eligible):
        node=g.node('GeometryNodeGroup');node.node_tree=contact()
        for key,value in (('Point',p),('Velocity',v),('Start',a),('End',b),('Start Velocity',va),('End Velocity',vb)):
            g.bind(g.xyz(*value),node.inputs[key])
        value=c.choose(g,eligible,node.outputs['Factor'],1e8)
        return c._stat(g,src,value) if reduce else value
    def distinct_contact(pfixed,pmouth,afixed,amouth,bfixed,bmouth):
        if not exact_mouths:return 1.
        same=pfixed*g.math('MAXIMUM',afixed*g.math('COMPARE',pmouth,amouth),bfixed*g.math('COMPARE',pmouth,bmouth))
        return 1.-same
    factor=test(P,V,A,B,VA,VB,different*g.math('COMPARE',other,next_owner)*
        distinct_contact(fixed,own_mouth,fixed_a,mouth_a,fixed_b,mouth_b))
    for row,before in ((g.math('MAXIMUM',at-1.,0.),True),(g.math('MINIMUM',at+1.,count-1.),False)):
        Q,W,neighbor,fixed_q,mouth_q=motion(row);a,b,va,vb=(Q,P,W,V) if before else (P,Q,V,W)
        eligible=different*g.math('COMPARE',owner,neighbor)*distinct_contact(fixed_a,mouth_a,fixed,own_mouth,fixed_q,mouth_q)
        factor=g.math('MINIMUM',factor,test(A,VA,a,b,va,vb,eligible))
    return c.choose(g,fixed,1e8,c._read(g,src,'st_cg_nominal',at)*factor)
